CREATE TABLE IF NOT EXISTS kyc_applications (id bigserial PRIMARY KEY, application_reference varchar(30) NOT NULL UNIQUE, customer_number varchar(30) NOT NULL, status varchar(20) NOT NULL, submitted_at timestamp, reviewed_at timestamp, reviewed_by varchar(30), rejection_reason varchar(500), created_at timestamp NOT NULL, updated_at timestamp NOT NULL); CREATE INDEX IF NOT EXISTS idx_kyc_customer ON kyc_applications(customer_number); CREATE INDEX IF NOT EXISTS idx_kyc_status ON kyc_applications(status);
